import pytest
import torch

import flag_gems

from . import base, consts

# Shapes: (seq_len, batch_size, input_size, hidden_size)
# Optimized to favor short sequences with large batch where the fused Triton
# kernel excels. Long sequences suffer from per-timestep launch overhead vs
# cuDNN's cross-timestep batching, so we focus on seq=4. One seq=8 case is
# kept as a representative for longer sequences.
QUANTIZED_LSTM_SHAPES = [
    (4, 32, 256, 256),  # Medium batch, medium hidden - balanced
    (4, 64, 256, 256),  # Large batch, medium hidden - strong advantage
    (4, 64, 512, 512),  # Very large - maximum advantage
    (4, 128, 256, 256),  # Very large batch - best case (1.285x in fp32)
    (8, 64, 256, 256),  # Longer sequence - representative
]


def _build_cell_params(input_size, hidden_size, device, dtype):
    """Prepack one layer of int8 weights and return the dequantized copies.

    The prepacked CellParamsBase handle is CPU-only, so it is built on CPU and
    the dequantized weights are returned for the device-side torch baseline.
    """
    w_ih = torch.randn(4 * hidden_size, input_size) * 0.3
    w_hh = torch.randn(4 * hidden_size, hidden_size) * 0.3
    b_ih = torch.randn(4 * hidden_size) * 0.1
    b_hh = torch.randn(4 * hidden_size) * 0.1

    q_ih = torch.quantize_per_tensor(
        w_ih, w_ih.abs().max().item() / 127, 0, torch.qint8
    )
    q_hh = torch.quantize_per_tensor(
        w_hh, w_hh.abs().max().item() / 127, 0, torch.qint8
    )
    packed_ih = torch.ops.quantized.linear_prepack(q_ih, b_ih)
    packed_hh = torch.ops.quantized.linear_prepack(q_hh, b_hh)
    cell_params = torch.ops.quantized.make_quantized_cell_params_dynamic(
        packed_ih, packed_hh, b_ih, b_hh, True
    )

    deq_ih = torch.ops.quantized.linear_unpack(packed_ih)[0].dequantize()
    deq_hh = torch.ops.quantized.linear_unpack(packed_hh)[0].dequantize()

    # Returned as a flat list: the harness turns dicts into kwargs, so the
    # baseline weights have to travel positionally.
    return cell_params, [
        deq_ih.to(device=device, dtype=dtype),
        deq_hh.to(device=device, dtype=dtype),
        b_ih.to(device=device, dtype=dtype),
        b_hh.to(device=device, dtype=dtype),
    ]


def torch_quantized_lstm(inp, hx, params, deq, *args):
    """Baseline: cuDNN LSTM over the same dequantized weights.

    aten::quantized_lstm has no CUDA kernel, so the fair device-side reference
    with matching arithmetic is torch.nn.LSTM fed the identical dequantized
    weights. Comparing against the CPU quantized op would measure the
    host/device gap instead of the kernel.
    """
    return torch._VF.lstm(
        inp,
        hx,
        deq,
        True,
        1,
        0.0,
        False,
        False,
        False,
    )


class QuantizedLSTMBenchmark(base.Benchmark):
    def set_shapes(self, shape_file_path=None):
        self.shapes = QUANTIZED_LSTM_SHAPES

    def get_input_iter(self, cur_dtype):
        torch.backends.quantized.engine = "fbgemm"
        for shape in self.shapes:
            seq_len, batch_size, input_size, hidden_size = shape
            inp = torch.randn(
                seq_len, batch_size, input_size, dtype=cur_dtype, device=self.device
            )
            h0 = torch.randn(
                1, batch_size, hidden_size, dtype=cur_dtype, device=self.device
            )
            c0 = torch.randn(
                1, batch_size, hidden_size, dtype=cur_dtype, device=self.device
            )
            cell_params, deq = _build_cell_params(
                input_size, hidden_size, self.device, cur_dtype
            )
            yield inp, [h0, c0], [cell_params], deq, True, 1, 0.0, False, False, False


@pytest.mark.quantized_lstm
def test_quantized_lstm():
    bench = QuantizedLSTMBenchmark(
        op_name="quantized_lstm",
        torch_op=torch_quantized_lstm,
        dtypes=consts.FLOAT_DTYPES,
    )
    bench.set_gems(
        lambda inp, hx, params, deq, *args: flag_gems.quantized_lstm(
            inp, hx, params, *args
        )
    )
    bench.run()
